#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned long lastSample = 0;
unsigned long phaseStart = 0;
bool sampled = false;
int alarmMode = 0;
bool sounding = false;

void setSound(bool on) {
  if (on == sounding) return;
  sounding = on;
  if (on) tone(6, 2000);
  else noTone(6);
}

void sampleDistance() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  if (!duration) return;
  float cm = duration * 0.0343f / 2.0f;
  int shown = (int)(cm + 0.5f);
  display.showNumberDec(shown, false);
  digitalWrite(13, cm < 30.0f ? HIGH : LOW);
  int nextMode = cm < 8.0f ? 2 : (cm < 15.0f ? 1 : 0);
  if (nextMode != alarmMode) {
    alarmMode = nextMode;
    phaseStart = millis();
    setSound(false);
  }
}

void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(8, LOW);
  digitalWrite(13, LOW);
  noTone(6);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  if (!sampled || now - lastSample >= 100UL) {
    sampled = true;
    lastSample = now;
    sampleDistance();
  }
  now = millis();
  if (alarmMode == 0) {
    setSound(false);
  } else {
    unsigned long period = alarmMode == 2 ? 200UL : 800UL;
    unsigned long onTime = alarmMode == 2 ? 100UL : 200UL;
    setSound((now - phaseStart) % period < onTime);
  }
}
